/*
 * dsh-plugin-mascot — configuration console.
 *
 * The page runs no server and touches nothing on the machine viewing it. It turns
 * choices into a YAML string, and — in the live preview — reads the artwork the
 * visitor already installed on their own DSH, in order to animate it here. That
 * read is the only thing this page ever asks of the host, and it goes through the
 * plugin's own allowlisted art route.
 *
 * The look catalogue comes from `site/catalog.json` and the skeleton from
 * `site/rig.js`, both generated by `scripts/build-site.mjs` from the plugin's own
 * sources, so neither can drift from what the plugin actually does.
 */

import { createPreview } from "./preview.js";

const REPO = "https://github.com/ZYAONS/dsh-plugin-mascot";
const STATE_KEY = "dsh-mascot-console";


/** Which per-character interface style each theme maps to, for the card art. */
const THEME_COLOURS = {
  rhodes: { accent: "#37e0d8", label: "CONSOLE", page: "closure" },
  mewtype: { accent: "#ff4d9d", label: "LIVE SET", page: "yuno" },
  rhine: { accent: "#5fb8f0", label: "RHINE LAB", page: "muelsyse" },
};

/** Human names for the page themes, for the header readout. */
const PAGE_THEME_NAMES = {
  auto: "neutral silver",
  closure: "blue on silver",
  yuno: "pink neon",
  muelsyse: "Rhine blue",
};

const state = {
  catalog: { characters: [], looks: [], version: "0.0.0", repository: REPO },
  plugin: true,
  character: "closure",
  /** Look ids the visitor turned off, per character. */
  off: new Set(),
  skeleton: true,
  animated: true,
  balance: true,
  mount: "name",
  dir: "",


  /**
   * Whether the visitor chose the neutral theme.
   *
   * `auto` is the silver that belongs to no character, and it is the default. Every
   * other theme is the selected character's own, which is why it is derived on each
   * render rather than stored: choosing a character's theme also selects that
   * character, so the two can be set from the header or from section 02 and can
   * never end up describing different people.
   */
  autoTheme: true,
  /** The theme last applied; a read-out, written by `applyTheme`. */
  theme: "auto",
  /**
   * The look the frame is showing, when the visitor picked one by clicking a card.
   * Distinct from the allowlist ticks: the ticks decide what the *plugin* may offer,
   * this decides what you are looking at.
   */
  previewLook: undefined,
  /** Set by `?preview=test`; renders the rig test pattern instead of a host. */
  previewTest: false,
};

const $ = (id) => document.getElementById(id);

/** Escape the two characters that could break out of the YAML snippet. */
const yamlString = (value) => `'${String(value).replace(/'/gu, "''")}'`;

/** Look up one character record. */
const characterOf = (id) => state.catalog.characters.find((entry) => entry.id === id);

/** The looks of one character, in declaration order. */
const looksOf = (id) => state.catalog.looks.filter((look) => look.character === id);

/**
 * The look the frame is showing: the one the visitor chose, or the first the plugin
 * would offer. Resolved against what is enabled, so unticking the look on screen
 * moves the frame on rather than leaving it showing something the plugin will not.
 */
function previewedLook() {
  const available = enabledLooks(state.character);
  return available.some((look) => look.id === state.previewLook) ? state.previewLook : available[0]?.id;
}

/** Whether a look is currently enabled. */
const lookOn = (id) => !state.off.has(id);

/** The looks that survive the visitor's choices; a look is only dropped when every
 * option of a character was switched off, in which case that character keeps all
 * of them rather than becoming unusable. */
function enabledLooks(characterId) {
  const all = looksOf(characterId);
  const on = all.filter((look) => lookOn(look.id));
  return on.length > 0 ? on : all;
}

//#region render
/**
 * The page theme a character wears.
 *
 * Derived, never chosen. The theme and the artwork on screen are two statements
 * about the same character, so a control that let them disagree was a control that
 * let the page contradict itself — picking Yuno and getting Closure's blue, or the
 * reverse. There is no theme state to get out of step, because there is no theme
 * state: it is a function of the selection.
 */
function pageThemeOf(characterId) {
  const character = characterOf(characterId);
  // An unknown character falls back to the page's own neutral theme, not to one of
  // the other characters' — the fallback should not be a claim about who this is.
  return THEME_COLOURS[character?.theme]?.page ?? "auto";
}

/**
 * Choose a page theme.
 *
 * A character's theme also selects that character, so the header buttons and the
 * cards in section 02 are two ways of saying one thing and cannot disagree. `auto`
 * is the neutral silver: it belongs to no character, so it claims nothing and
 * leaves the selection alone.
 */
function chooseTheme(choice) {
  if (PAGE_THEME_NAMES[choice] === undefined) return;
  state.autoTheme = choice === "auto";
  if (choice !== "auto") {
    const character = state.catalog.characters.find((entry) => THEME_COLOURS[entry.theme]?.page === choice);
    if (character !== undefined) {
      state.character = character.id;
      // A look belongs to one character, so a choice made for the last one is not a
      // choice about this one.
      state.previewLook = undefined;
      renderCharacters();
      renderLooks();
    }
  }
  render();
}

/** Apply the theme, and light the control that set it. */
function applyTheme() {
  const theme = state.autoTheme ? "auto" : pageThemeOf(state.character);
  state.theme = theme;
  for (const button of $("theme").querySelectorAll("button")) {
    button.dataset.on = button.dataset.themeChoice === theme ? "1" : "0";
  }
  document.documentElement.dataset.theme = theme;
  $("m-theme").textContent = PAGE_THEME_NAMES[theme] ?? theme;
  const character = characterOf(state.character);
  $("theme-name").textContent = `${character?.nameEn ?? state.character} · ${PAGE_THEME_NAMES[theme] ?? theme}`;
  $("theme-swatch").style.background = getComputedStyle(document.documentElement).getPropertyValue("--signal").trim();
}

/** Persist the console state so a reload keeps the visitor's choices. */
function save() {
  try {
    window.localStorage.setItem(STATE_KEY, JSON.stringify({
      plugin: state.plugin,
      character: state.character,
      off: [...state.off],
      skeleton: state.skeleton,
      animated: state.animated,
      balance: state.balance,
      mount: state.mount,
      dir: state.dir,
      autoTheme: state.autoTheme,

    }));
  } catch {
    /* private mode — the choices simply do not persist */
  }
}

/** Restore a previous session, tolerating anything unreadable. */
function load() {
  try {
    const raw = window.localStorage.getItem(STATE_KEY);
    if (raw === null) return;
    const saved = JSON.parse(raw);
    if (typeof saved.plugin === "boolean") state.plugin = saved.plugin;
    if (typeof saved.character === "string") state.character = saved.character;
    if (Array.isArray(saved.off)) state.off = new Set(saved.off);
    if (typeof saved.skeleton === "boolean") state.skeleton = saved.skeleton;
    if (typeof saved.animated === "boolean") state.animated = saved.animated;
    if (typeof saved.balance === "boolean") state.balance = saved.balance;
    if (saved.mount === "name" || saved.mount === "file") state.mount = saved.mount;
    if (typeof saved.dir === "string") state.dir = saved.dir;
    if (typeof saved.autoTheme === "boolean") state.autoTheme = saved.autoTheme;

  } catch {
    /* unreadable state is not worth reporting; defaults are fine */
  }
}

/** A Windows or POSIX path as a file: URL, which is what a patch row wants. */
function fileUrl(path) {
  const trimmed = String(path).trim().replace(/[\\/]+$/u, "");
  if (trimmed === "") return "";
  if (/^file:/iu.test(trimmed)) return trimmed;
  if (/^[a-z]:[\\/]/iu.test(trimmed)) return `file:///${trimmed.replace(/\\/gu, "/")}`;
  return `file://${trimmed.startsWith("/") ? "" : "/"}${trimmed}`;
}

/** Render the character cards. */
function renderCharacters() {
  const host = $("characters");
  host.textContent = "";
  for (const character of state.catalog.characters) {
    const theme = THEME_COLOURS[character.theme] ?? { accent: "#ffd400", label: "—" };
    const card = document.createElement("div");
    card.className = "card";
    card.dataset.on = character.id === state.character ? "1" : "0";
    card.tabIndex = 0;
    card.innerHTML = [
      `<span class="check"></span>`,
      `<div class="code">${theme.label} / ${character.id}</div>`,
      `<div class="name">${character.nameEn ?? character.name}</div>`,
      `<div class="latin">${character.latin}</div>`,
      `<div class="role">${character.roleEn ?? character.role}<br>${character.taglineEn ?? character.tagline ?? ""}</div>`,
      `<div class="swatch" style="background:${theme.accent}"></div>`,
    ].join("");
    const choose = () => {
      state.character = character.id;
      // The card and the header button say the same thing, so both move together.
      state.autoTheme = false;
      // A look belongs to one character, so a choice made for the last one is not a
      // choice about this one.
      state.previewLook = undefined;
      // And the theme follows the character, unless the visitor has asked for the
      // neutral one — which describes no character and so cannot contradict this.
      if (state.theme !== "auto") state.theme = pageThemeOf(character.id);
      renderCharacters();
      renderLooks();
      render();
    };
    card.addEventListener("click", choose);
    card.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        choose();
      }
    });
    host.append(card);
  }
}

/** Render the look checkboxes for the selected character. */
function renderLooks() {
  const host = $("looks");
  host.textContent = "";
  for (const look of looksOf(state.character)) {
    const card = document.createElement("div");
    card.className = "card";
    card.dataset.on = lookOn(look.id) ? "1" : "0";
    card.dataset.preview = look.id === previewedLook() ? "1" : "0";
    card.tabIndex = 0;
    card.innerHTML = [
      `<span class="check"></span>`,
      `<div class="code">${look.id}</div>`,
      `<div class="name">${look.nameEn ?? look.name}</div>`,
      look.animated ? `<span class="badge">Multi-frame</span>` : "",
    ].join("");
    // One click does both, because both are what the visitor means by it: tick the
    // look into the plugin's allowlist, and put it in the frame so they can see the
    // thing they just picked.
    const toggle = () => {
      if (lookOn(look.id)) state.off.add(look.id);
      else state.off.delete(look.id);
      state.previewLook = look.id;
      renderLooks();
      render();
    };
    card.addEventListener("click", toggle);
    card.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        toggle();
      }
    });
    host.append(card);
  }
}

/** Paint one toggle element from the state. */
function paintToggle(id, on) {
  const node = $(id);
  node.dataset.on = on ? "1" : "0";
  node.setAttribute("aria-checked", on ? "true" : "false");
}

/** The YAML the visitor pastes into their profile. */
function buildConfig() {
  const character = characterOf(state.character);
  const looks = enabledLooks(state.character).map((look) => look.id);
  const lines = [];

  if (!state.plugin) {
    lines.push("# Mascot plugin: disabled — leaving the entry out is what disables it.");
    lines.push("# To turn it back on, drop the leading # from the block below.");
    lines.push("#");
    lines.push("# - insert:");
    lines.push("#     - id: mascot");
    lines.push(`#       name: ${state.mount === "file" ? "file:///…/dsh-plugin-mascot/lib/index.js" : "dsh-plugin-mascot"}`);
    return lines.join("\n");
  }

  lines.push("# DSH profile patch — paste into ~/.dsh/profiles/desktop/cordis.patch.yml");
  lines.push("# Do not edit cordis.yml: it is rewritten to [] on every launch.");
  lines.push("- insert:");
  lines.push("    - id: mascot");
  if (state.mount === "file") {
    const resolved = fileUrl(state.dir);
    lines.push("      # Mounted by absolute path: the plugin has no runtime dependencies,");
    lines.push("      # so it does not need to be installed into the profile.");
    lines.push(`      name: ${yamlString(resolved === "" ? "file:///path/to/dsh-plugin-mascot/lib/index.js" : `${resolved}/lib/index.js`)}`);
  } else {
    lines.push("      name: dsh-plugin-mascot");
  }
  lines.push("      config:");
  lines.push(`        # Default character: ${character === undefined ? state.character : (character.nameEn ?? character.name)}`);
  lines.push(`        character: ${state.character}`);
  const available = enabledLooks(state.character);
  const preferred = available.find((look) => (state.animated ? true : !look.animated)) ?? available[0];
  lines.push("        # Default look within that character. Empty means the plugin picks");
  lines.push("        # its first installed one, which is what this says before the");
  lines.push("        # catalogue has loaded.");
  lines.push(`        look: ${preferred === undefined ? '""' : preferred.id}`);
  lines.push("        # Allowlist of looks the panel may offer. An empty list means");
  lines.push("        # every installed look.");
  lines.push("        looks:");
  for (const id of looks) lines.push(`          - ${id}`);
  lines.push("        # Skeletal animation: three bones rigged from the silhouette, driving");
  lines.push("        # a skinned mesh. Falls back to a still image without WebGL2.");
  lines.push(`        skeleton: ${state.skeleton}`);
  lines.push("        # Account balance in the panel; off means the browser never queries it.");
  lines.push(`        balance: ${state.balance}`);
  if (!state.animated) {
    lines.push("        # Multi-frame looks were switched off in the console, so only");
    lines.push("        # single-frame looks are allowlisted above.");
  }
  return lines.join("\n");
}

/** Re-render everything derived from state. */
function render() {
  paintToggle("t-plugin", state.plugin);
  paintToggle("t-balance", state.balance);
  paintToggle("t-skeleton", state.skeleton);
  paintToggle("t-animated", state.animated);
  $("s-plugin").className = state.plugin ? "status" : "status off";
  $("s-plugin").innerHTML = `<i></i>${state.plugin ? "Enabled" : "Disabled"}`;
  $("dir-field").classList.toggle("hidden", state.mount !== "file");
  $("sec-look").classList.toggle("hidden", !state.plugin);
  $("sec-character").classList.toggle("hidden", !state.plugin);
  $("output").textContent = buildConfig();
  // Applied last, and on every render, because "auto" resolves against the
  // character and the character can change in the same pass.
  applyTheme();
  // The preview follows the selection: switching character switches what floats in
  // the frame, which is the point of having it here at all.
  paintCredit(state.character);
  const preview = previewRef.current;
  if (preview !== null && preview !== undefined) {
    preview.show(state.character, previewedLook()).catch(() => {});
  }
  save();
}
//#endregion

//#region preview
/**
 * Who owns the character on screen.
 *
 * Shown next to the artwork rather than only in the footer: the console displays
 * someone else's character, and the credit belongs where the reader is looking.
 * See COPYRIGHT.md — this project ships no artwork and claims no rights in it.
 */
const CREDITS = {
  closure: { work: "Arknights", owner: "Hypergryph", note: "unofficial fan project" },
  yuno: { work: "BanG Dream! / Mugendai MewType", owner: "Bushiroad", note: "unofficial fan project" },
};

/** Paint the attribution for the selected character. */
function paintCredit(characterId) {
  const credit = CREDITS[characterId];
  const node = $("preview-credit");
  if (credit === undefined) {
    node.textContent = "";
    return;
  }
  const character = characterOf(characterId);
  node.innerHTML =
    `Artwork: <b>${character?.nameEn ?? characterId}</b> © <b>${credit.owner}</b> — ${credit.work}. ` +
    `Shown from its original source; not redistributed by this project. ${credit.note}, not affiliated with or endorsed by the rights holder.`;
}
/** The live preview, created on boot. A ref so `render` can reach it. */
const previewRef = { current: null };

/** Paint one preview status line. */
function paintPreviewStatus({ kind, message }) {
  const node = $("preview-status");
  node.textContent = message;
  node.dataset.kind = kind;
  const badge = $("s-preview");
  // `isLive` means the plugin answered on this origin; a supplied file counts too.
  const connected = previewRef.current?.isLive() === true || $("preview-host").querySelector("canvas, .preview-still") !== null;
  badge.className = connected ? "status" : "status off";
  badge.innerHTML = `<i></i>${connected ? "Previewing" : "Not connected"}`;
}

/** Create the preview and wire its controls. */
async function setupPreview() {
  const preview = createPreview($("preview-host"), paintPreviewStatus);
  preview.setCatalogue(state.catalog);
  previewRef.current = preview;

  // The skeleton needs no artwork at all, so it is the one control that always has
  // something to show — on either copy, for any look.
  $("preview-skeleton").addEventListener("click", async () => {
    await preview.useSkeleton(state.character, previewedLook());
    paintPreviewStatusRefresh();
  });
  $("preview-file").addEventListener("change", async (event) => {
    const file = event.target.files?.[0];
    if (file === undefined) return;
    await preview.useFile(file);
    paintPreviewStatusRefresh();
  });

  // Which of the two lives this page is depends on where it is served from, and
  // that decides what the section can honestly offer.
  const mode = await preview.detect();
  if (mode === "local") {
    $("preview-note").textContent = "Served by the plugin itself, so the frame below is reading the artwork installed on this machine.";
    await preview.show(state.character, previewedLook());
    const drawn = $("preview-host").querySelector("canvas, .preview-still") !== null;
    preview.report(drawn
      ? "Live from this machine: showing the artwork you installed, rigged and animated by the same skeleton the plugin runs."
      : "Connected to the plugin, but nothing could be drawn — see the note below.");
    return;
  }

  $("preview-note").innerHTML =
    "This copy is the published one, so it shows the artwork from the sources declared in " +
    "<code>art/looks.json</code>. A host that sends no CORS header cannot be read into WebGL, so only " +
    "artwork it does send headers for is deformed by the rig. Run <code>npm run art:publish</code> and " +
    "commit <code>docs/art/</code> to animate everything.";

  // `?preview=test` drives the synthetic figure through the WebGL path. It is not a
  // control on the page — the page offers the skeleton, which is the useful thing —
  // but it is the only way to exercise measure -> auto-rig -> skin -> animate with
  // no artwork present at all, so the self-test still uses it.
  if (state.previewTest) {
    await preview.useTestPattern();
    paintPreviewStatusRefresh();
    return;
  }
  // The selected look, not the character's first one: the frame is meant to show
  // what the cards above it say is on screen.
  await preview.show(state.character, previewedLook());
  paintPreviewStatusRefresh();
}

/** Re-read the connection badge after a connect or file pick changed it. */
function paintPreviewStatusRefresh() {
  const node = $("preview-status");
  paintPreviewStatus({ kind: node.dataset.kind ?? "idle", message: node.textContent });
}
//#endregion

//#region events
/** Wire one toggle element to a state setter. */
function bindToggle(id, apply) {
  const node = $(id);
  const flip = () => {
    apply(!node.dataset.on || node.dataset.on !== "1");
    render();
  };
  node.addEventListener("click", flip);
  node.addEventListener("keydown", (event) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      flip();
    }
  });
}

/** Copy text, preferring the async clipboard and falling back to a textarea. */
async function copyText(text) {
  try {
    await navigator.clipboard.writeText(text);
    return true;
  } catch {
    const area = document.createElement("textarea");
    area.value = text;
    area.style.position = "fixed";
    area.style.opacity = "0";
    document.body.append(area);
    area.select();
    const ok = document.execCommand("copy");
    area.remove();
    return ok;
  }
}

/** Save a string as a file, entirely client-side. */
function download(name, text) {
  const blob = new Blob([text], { type: "text/yaml;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = name;
  document.body.append(anchor);
  anchor.click();
  anchor.remove();
  URL.revokeObjectURL(url);
}

/** Show a transient label on a button. */
function flash(button, label) {
  const original = button.textContent;
  button.textContent = label;
  button.disabled = true;
  window.setTimeout(() => {
    button.textContent = original;
    button.disabled = false;
  }, 1400);
}
//#endregion

/**
 * Read a deep link.
 *
 * `?theme=`, `?character=` and `?preview=` let a link point at a specific
 * configuration — "show me the Yuno version" is a URL — and `?preview=test` also
 * makes the whole chain testable without a host: a headless run of that link
 * exercises measure → auto-rig → skin → animate in the page itself.
 *
 * A query parameter outranks stored state, because a link that says what it wants
 * should not be silently overridden by a previous visit.
 */
function applyQuery() {
  let query;
  try {
    query = new URLSearchParams(window.location.search);
  } catch {
    return;
  }

  const character = query.get("character");
  if (character !== null && character !== "") {
    state.character = character;
    // Applied on the next render, once the catalogue can resolve the mapping.
    state.autoTheme = false;
  }
  const theme = query.get("theme");
  // `?theme=` moves the character too, through the same rule the buttons use.
  if (theme !== null && theme !== "" && PAGE_THEME_NAMES[theme] !== undefined) chooseTheme(theme);
  const look = query.get("look");
  if (look !== null && look !== "") state.previewLook = look;
  const preview = query.get("preview");
  if (preview === "test") state.previewTest = true;
}

/** Boot: fetch the catalogue, wire the controls, draw. */
async function main() {
  load();
  applyQuery();
  try {
    const response = await fetch("site/catalog.json", { cache: "no-cache" });
    if (response.ok) state.catalog = await response.json();
  } catch {
    /* the page still works, just with an empty catalogue */
  }
  // The preview was created before the catalogue arrived, so hand it over now that
  // it has: on the published copy the catalogue is where the preview finds both the
  // framing and the source URLs for every look.
  previewRef.current?.setCatalogue(state.catalog);

  // Reconcile the theme with the character, now that the catalogue can answer which
  // theme a character wears. This has to run *after* the fetch: before it, no character
  // is known, and a reconciliation would read that as "no theme" and discard the
  // visitor's stored choice. A stored character-theme can also disagree with the
  // character a link names — last visit's preference against a `?character=` — which is
  // precisely the mismatch the pairing rule exists to prevent.
  if (state.theme !== "auto") state.theme = pageThemeOf(state.character);

  const characters = state.catalog.characters ?? [];
  if (characters.length > 0 && !characters.some((entry) => entry.id === state.character)) {
    state.character = characters[0].id;
  }

  $("m-version").textContent = state.catalog.version ?? "—";
  $("m-characters").textContent = String(characters.length);
  $("m-looks").textContent = String((state.catalog.looks ?? []).length);
  $("f-repo").href = state.catalog.repository ?? REPO;
  $("f-readme").href = `${state.catalog.repository ?? REPO}#readme`;
  $("download-repo").href = `${state.catalog.repository ?? REPO}/archive/refs/heads/main.zip`;

  bindToggle("t-plugin", (value) => { state.plugin = value; });
  bindToggle("t-balance", (value) => { state.balance = value; });
  bindToggle("t-skeleton", (value) => { state.skeleton = value; });
  bindToggle("t-animated", (value) => { state.animated = value; });



  for (const button of $("theme").querySelectorAll("button")) {
    button.addEventListener("click", () => {
      chooseTheme(button.dataset.themeChoice);
    });
  }

  for (const button of $("mount").querySelectorAll("button")) {
    button.addEventListener("click", () => {
      state.mount = button.dataset.mount;
      for (const peer of $("mount").querySelectorAll("button")) {
        peer.dataset.on = peer === button ? "1" : "0";
      }
      render();
    });
    button.dataset.on = button.dataset.mount === state.mount ? "1" : "0";
  }

  $("dir").addEventListener("input", (event) => {
    state.dir = event.target.value;
    render();
  });
  $("dir").value = state.dir;

  $("copy").addEventListener("click", async () => {
    const ok = await copyText(buildConfig());
    flash($("copy"), ok ? "Copied" : "Copy failed");
  });
  $("download-config").addEventListener("click", () => {
    download("cordis.patch.yml", `${buildConfig()}\n`);
    flash($("download-config"), "Downloaded");
  });

  renderCharacters();
  renderLooks();
  render();
  // Started, not awaited, and after the first render: setting the preview up loads
  // artwork over the network, and the console must not wait on a decoration to become
  // usable. It fills in when it can, and drives itself from then on.
  setupPreview().catch(() => {
    /* a preview that cannot start leaves the console exactly as it is */
  });
}

main();
